648	                                error.textContent = 'Please enter a valid email address';
649	                            } else {
650	                                error.textContent = 'Invalid input';
651	                            }
652	                        }
653	                        return false;
654	                    }
655	
656	                    if (error) {
657	                        error.classList.remove('show');
658	                    }
659	                    return true;
660	                };
