662	                const inputs = contactForm.querySelectorAll('input, textarea');
663	                inputs.forEach(input => {
664	                    input.addEventListener('blur', () => validateField(input));
665	                });
666	
667	                contactForm.addEventListener('submit', function(e) {
668	                    e.preventDefault();
669	                    let isValid = true;
670	                    const feedback = document.getElementById('form-feedback');
671	                    feedback.className = 'form-feedback';
672	
673	                    inputs.forEach(input => {
674	                        if (!validateField(input)) isValid = false;
