        return false;
    }

    if (!field.checkValidity()) {
        if (error) {
            error.classList.add('show');
            if (field.type === 'email') {
                error.textContent = 'Please enter a valid email address';
            } else {
                error.textContent = 'Invalid input';
            }
        }
        return false;
    }

    if (error) {
        error.classList.remove('show');
    }
    return true;
